mapper.select:
select oc.id as id,oc.create_time as createTime,oc.role_code as roleCode,oc.score as score,oc.num as num,oc.total_score as totalScore, su.nickname as userName,su.avatar as userAvatar,su.phone as userPhone from job_evaluate oc left join sys_user su on su.id=oc.user_id WHERE 1=1
AND oc.user_id = #{params.userId}
AND oc.role_code = #{params.roleCode}
and ( su.nickname like CONCAT('%',#{params.keyword},'%') or su.phone like CONCAT('%',#{params.keyword},'%') )
order by oc.create_time desc
